if not Path("ml/eventos.py").exists():
    sys.exit("Aplique antes o lote 1.")
if Path("ml/perfis.py").exists():
    sys.exit("O lote 2 já foi aplicado.")

ARQUIVOS = {
    'apps/fontes/repositorios/referencia.py': '"""Leituras dos cadastros de referência (distritos, e depois bairros, CNES...)."""\n\nfrom . import conexao\n\nSILVER_DISTRITOS = "silver_distritos_sanitarios"\nSILVER_BAIRROS = "silver_bairros"\nSILVER_AREAS_RISCO = "silver_areas_risco"\nSILVER_COMUNIDADES = "silver_comunidades"\nSILVER_REDE_APOIO = "silver_rede_apoio"\nSILVER_UNIDADES = "silver_unidades_saude"\n\n\ndef distritos_features():\n    """As Features GeoJSON dos distritos, prontas para o Leaflet."""\n    return list(conexao.banco()[SILVER_DISTRITOS].find({}, {"_id": 0}))\n\n\ndef total_distritos():\n    return conexao.banco()[SILVER_DISTRITOS].count_documents({})\n\n\ndef areas_risco():\n    """Bairros que contêm áreas R3/R4, com as localidades do plano."""\n    return list(conexao.banco()[SILVER_AREAS_RISCO].find({}, {"_id": 0}))\n\n\ndef comunidades():\n    """Comunidades de Interesse Social, sem o ponto de rótulo (o mapa não usa)."""\n    return list(conexao.banco()[SILVER_COMUNIDADES].find({}, {"_id": 0, "ponto_rotulo": 0}))\n\n\ndef rede_apoio(tipo=None):\n    """Abrigos, escolas e CRAS; tipo filtra um deles."""\n    filtro = {"tipo": tipo} if tipo else {}\n    return list(conexao.banco()[SILVER_REDE_APOIO].find(filtro, {"_id": 0}))\n\n\ndef unidades_saude(codigos_tipo=None):\n    """Unidades com coordenada (sem ela quebrariam a camada do mapa); filtra por tipo CNES."""\n    filtro = {"localizacao": {"$ne": None}}\n    if codigos_tipo:\n        filtro["codigo_tipo"] = {"$in": list(codigos_tipo)}\n    projecao = {"_id": 0, "localizacao": 1, "nome": 1, "tipo": 1, "codigo_tipo": 1, "bairro": 1, "turno": 1}\n    return list(conexao.banco()[SILVER_UNIDADES].find(filtro, projecao))\n\n\ndef total_unidades():\n    """Mesmo critério do mapa: só unidades com coordenada."""\n    return conexao.banco()[SILVER_UNIDADES].count_documents({"localizacao": {"$ne": None}})\n\n\ndef bairros():\n    """Bairros com limite e população (IBGE, Censo 2022)."""\n    return list(conexao.banco()[SILVER_BAIRROS].find({}, {"_id": 0}))\n\n\ndef vulnerabilidade():\n    """Índice de vulnerabilidade por bairro (gold, etl/derivados/vulnerabilidade.py)."""\n    return list(conexao.banco()["gold_vulnerabilidade_bairro"].find({}, {"_id": 0, "coletado_em": 0}))\n\n\ndef perfis():\n    """Perfil de risco de cada bairro (gold, ml/perfis.py)."""\n    return list(conexao.banco()["gold_perfil_bairro"].find({}, {"_id": 0, "chave": 1, "perfil": 1, "grupo": 1}))\n\n',
    'apps/mapa/static/mapa/mapa.js': '// Tela: mapa/mapa.html\n// Dados do servidor chegam pelo json_script do template (o Django escapa o conteúdo).\n\n// 1. Inicializa o mapa centralizado em Recife\nconst map = L.map(\'map\').setView([-8.05, -34.9], 12);\n\n// 2. Adiciona a camada de mapa (tiles da Esri)\nL.tileLayer(\'https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}\', {\n  attribution: \'Tiles &copy; Esri\'\n}).addTo(map);\n\n// 3. Busca os distritos no MongoDB via API\n// O GeoJSON do portal do Recife traz apenas o campo numerico\n// \'cdistscodi\' (1 a 8), sem o nome do distrito.\nconst ROMANOS = [\'I\', \'II\', \'III\', \'IV\', \'V\', \'VI\', \'VII\', \'VIII\'];\n\nfunction nomeDistrito(props) {\n  const codigo = props && props.cdistscodi;\n  return codigo && ROMANOS[codigo - 1] ? \'DS \' + ROMANOS[codigo - 1] : null;\n}\n\n// Cor por nível: vem dos gatilhos reais de chuva e maré (/api/situacao-distritos/)\nconst CORES_RISCO = { \'ALTO\': \'#ef4444\', \'MÉDIO\': \'#f59e0b\', \'NORMAL\': \'#22c55e\', \'SEM DADO\': \'#94a3b8\' };\nlet situacao = {};\n\nfunction corDoDistrito(nome) {\n  const d = situacao[nome];\n  return (d && CORES_RISCO[d.nivel]) || CORES_RISCO[\'SEM DADO\'];\n}\n\nfetch(\'/api/situacao-distritos/\')\n  .then(r => r.json())\n  .then(dados => {\n    dados.distritos.forEach(d => { situacao[d.nome] = d; });\n    const alvo = new URLSearchParams(location.search).get(\'distrito\');\n    if (alvo && situacao[alvo]) { distritoSelecionado = alvo; selectDistrict(alvo); }\n    if (typeof redesenharDistritos === \'function\') redesenharDistritos();\n  })\n  .catch(err => console.error(\'Erro ao carregar a situação dos distritos:\', err));\n\nlet camadaDistritos = null;\nlet distritoSelecionado = null;\n// roxo nao colide com nenhuma outra cor do mapa: risco (vermelho,\n// amarelo, verde), chuva (azuis) e mouse (cinza-escuro)\nconst COR_SELECAO = \'#7c3aed\';\n\nfunction chuvaLigada() {\n  return document.getElementById(\'camada-chuva\').checked;\n}\n\nfunction riscoLigado() {\n  return document.getElementById(\'camada-risco\').checked;\n}\n\nfunction arboLigado() {\n  return document.getElementById(\'camada-arbo\').checked;\n}\n\n// as camadas de risco e de arboviroses pintam os mesmos bairros:\n// ligar uma desliga a outra, para os polígonos não se sobreporem\nfunction desligar(id) {\n  const caixa = document.getElementById(id);\n  if (caixa.checked) {\n    caixa.checked = false;\n    caixa.dispatchEvent(new Event(\'change\'));\n  }\n}\n\n// com uma camada tematica por cima, os distritos viram so contorno\nfunction distritosEmContorno() {\n  return chuvaLigada() || riscoLigado() || arboLigado() || comLigado() || vulLigado() || perfilLigado();\n}\n\n// o painel "Nivel de risco" descreve a cor dos distritos, que some\n// quando eles viram contorno\nfunction atualizarPainelRisco() {\n  document.getElementById(\'painel-risco\').style.opacity = distritosEmContorno() ? \'0.4\' : \'1\';\n}\n\nfunction formatarMm(mm) {\n  if (mm === null || mm === undefined) return \'sem dado\';\n  return mm.toLocaleString(\'pt-BR\', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + \' mm\';\n}\n\n// Tres estados visuais:\n//  - normal: preenchido pela cor de risco\n//  - chuva ligada: so um contorno fino e tracejado, para a borda\n//    grossa das zonas (por baixo) ser a linha dominante\n//  - selecionado: contorno grosso e escuro enquanto o card estiver aberto,\n//    para ligar visualmente o card ao poligono\nfunction estiloDistrito(feature) {\n  const selecionado = nomeDistrito(feature.properties) === distritoSelecionado;\n  if (distritosEmContorno()) {\n    return {\n      fillColor: COR_SELECAO,\n      fillOpacity: selecionado ? 0.15 : 0,\n      color: selecionado ? COR_SELECAO : \'#64748b\',\n      weight: selecionado ? 4 : 1,\n      dashArray: selecionado ? null : \'3 4\'\n    };\n  }\n  return {\n    fillColor: corDoDistrito(nomeDistrito(feature.properties)),\n    fillOpacity: 0.45,\n    color: selecionado ? COR_SELECAO : \'#0f172a\',\n    weight: selecionado ? 4 : 1.5,\n    dashArray: null\n  };\n}\n\n// destaque ao passar o mouse: deixa claro a que poligono a dica se refere\nfunction destacar(layer) {\n  layer.setStyle({\n    weight: 4,\n    color: \'#0f172a\',\n    dashArray: null,\n    fillColor: distritosEmContorno() ? \'#0f172a\' : layer.options.fillColor,\n    fillOpacity: distritosEmContorno() ? 0.18 : 0.7\n  });\n  // com o risco ligado, nao puxa o distrito para cima: esconderia os bairros\n  if (!riscoLigado() && !arboLigado() && !comLigado()) layer.bringToFront();\n}\n\nfunction redesenharDistritos() {\n  if (camadaDistritos) camadaDistritos.setStyle(estiloDistrito);\n}\n\nfetch(\'/api/distritos/\')\n  .then(response => response.json())\n  .then(data => {\n    const camada = L.geoJSON(data, {\n      style: estiloDistrito,\n      onEachFeature: function (feature, layer) {\n        const nome = nomeDistrito(feature.properties);\n        if (nome) {\n          // dica dinamica: com a chuva ligada, mostra a chuva medida do distrito\n          layer.bindTooltip(function () {\n            const zona = chuvaLigada() && zonaDoDistrito[nome];\n            return zona\n              ? \'<strong>\' + nome + \'</strong><br>\' + formatarMm(zona.chuva_24h_mm) + \' em 24h\' +\n                (zona.estacao ? \'<br>pior pluviômetro: \' + zona.estacao : \'\')\n              : \'<strong>\' + nome + \'</strong>\';\n          }, { sticky: true });\n        }\n        layer.on(\'mouseover\', function () { destacar(layer); });\n        layer.on(\'mouseout\', function () { camadaDistritos.resetStyle(layer); });\n        layer.on(\'click\', function () {\n          distritoSelecionado = nome;\n          redesenharDistritos();\n          selectDistrict(nome);\n        });\n      }\n    }).addTo(map);\n    camadaDistritos = camada;\n\n    // enquadra o mapa nos limites reais dos distritos\n    if (camada.getBounds().isValid()) {\n      map.fitBounds(camada.getBounds(), { padding: [20, 20] });\n    }\n  })\n  .catch(err => console.error(\'Erro ao carregar distritos:\', err));\n\n\n// ─── Camada: unidades de saúde (CNES) ───────────────────────\n// 410 pontos. circleMarker em vez de marker: não carrega ícone\n// por ponto, o que mantém o mapa fluido nesse volume.\nconst CORES_TIPO = {\n  2: \'#2563eb\',   // UBS\n  5: \'#dc2626\',   // hospital geral\n  7: \'#dc2626\',   // hospital especializado\n  4: \'#7c3aed\',   // policlínica\n  20: \'#ea580c\',  // pronto-socorro geral\n  21: \'#ea580c\',  // pronto-socorro especializado\n  73: \'#ea580c\',  // UPA\n  42: \'#0d9488\',  // SAMU\n  40: \'#0d9488\',  // unidade móvel\n  50: \'#ca8a04\',  // vigilância em saúde\n};\n\nconst camadaUnidades = L.layerGroup();\n\nfetch(\'/api/unidades/\')\n  .then(r => r.json())\n  .then(dados => {\n    L.geoJSON(dados, {\n      pointToLayer: function (feature, latlng) {\n        const p = feature.properties;\n        return L.circleMarker(latlng, {\n          radius: 5,\n          fillColor: CORES_TIPO[p.codigo_tipo] || \'#64748b\',\n          color: \'#ffffff\',\n          weight: 1.5,\n          fillOpacity: 0.9\n        });\n      },\n      onEachFeature: function (feature, layer) {\n        const p = feature.properties;\n        layer.bindPopup(\n          \'<strong>\' + (p.nome || \'Sem nome\') + \'</strong><br>\' +\n          \'<span style="color:#64748b">\' + (p.tipo || \'\') + \'</span><br>\' +\n          (p.bairro && p.bairro !== \'SN\' ? \'Bairro: \' + p.bairro + \'<br>\' : \'\') +\n          (p.turno ? \'<small>\' + p.turno + \'</small>\' : \'\')\n        );\n      }\n    }).addTo(camadaUnidades);\n\n    camadaUnidades.addTo(map);\n\n    const total = dados.features.length;\n    document.getElementById(\'contador-unidades\').innerText = total ? \'(\' + total + \')\' : \'(indisponível)\';\n    if (!total) document.getElementById(\'camada-unidades\').disabled = true;\n  })\n  .catch(err => console.error(\'Erro ao carregar unidades:\', err));\n\n// liga/desliga a camada pelo checkbox\ndocument.getElementById(\'camada-unidades\')\n  .addEventListener(\'change\', function (e) {\n    if (e.target.checked) {\n      map.addLayer(camadaUnidades);\n    } else {\n      map.removeLayer(camadaUnidades);\n    }\n  });\n\n\n// ─── Camada: chuva medida por distrito (CEMADEN) ────────────\n// O modelo enxerga o Recife em poucas celulas; distritos na mesma\n// celula recebem a mesma chuva. Cada zona e um poligono unico com\n// um unico valor - em vez de repetir o numero em varios distritos.\nfunction corChuva(mm) {\n  if (mm < 1) return \'#dbeafe\';\n  if (mm < 10) return \'#93c5fd\';\n  if (mm < 30) return \'#3b82f6\';\n  if (mm < 50) return \'#1d4ed8\';\n  return \'#1e3a8a\';\n}\n\nconst camadaChuva = L.layerGroup();\nconst zonaDoDistrito = {};\n\nconst legendaChuva = L.control({ position: \'bottomright\' });\nlegendaChuva.onAdd = function () {\n  const div = L.DomUtil.create(\'div\');\n  div.style.cssText = \'background:#fff;padding:8px 10px;border-radius:6px;\' +\n    \'font-size:11px;line-height:1.6;box-shadow:0 1px 3px rgba(0,0,0,.2)\';\n  const faixas = [[0, \'< 1\'], [1, \'1–10\'], [10, \'10–30\'], [30, \'30–50\'], [50, \'≥ 50\']];\n  div.innerHTML = \'<strong>Chuva 24h (mm)</strong><br>\' +\n    faixas.map(([v, rotulo]) =>\n      \'<i style="display:inline-block;width:12px;height:12px;margin-right:6px;\' +\n      \'vertical-align:middle;background:\' + corChuva(v + 0.1) + \'"></i>\' + rotulo\n    ).join(\'<br>\') +\n    \'<br><span style="color:#64748b">Pior pluviômetro do distrito<br>Dados da Rede Observacional<br>do CEMADEN/MCTIC</span>\';\n  return div;\n};\n\nfetch(\'/api/chuva-distritos/\')\n  .then(r => r.json())\n  .then(dados => {\n    L.geoJSON(dados, {\n      // nao-interativa: nunca rouba o mouse dos distritos\n      interactive: false,\n      style: function (feature) {\n        return {\n          fillColor: feature.properties.chuva_24h_mm === null ? \'#e2e8f0\' : corChuva(feature.properties.chuva_24h_mm),\n          fillOpacity: 0.45,\n          color: \'#1e3a8a\',\n          weight: 1.5\n        };\n      },\n      onEachFeature: function (feature, layer) {\n        const p = feature.properties;\n        p.distritos.forEach(d => { zonaDoDistrito[d.nome] = p; });\n\n        // rotulo fixo dentro da zona: o valor fica visivel mesmo quando\n        // todas as zonas caem na mesma faixa de cor. O ponto vem do\n        // conector (garantidamente dentro do poligono); sem ele, usa o\n        // centro do retangulo envolvente.\n        const ponto = p.ponto_rotulo\n          ? [p.ponto_rotulo[1], p.ponto_rotulo[0]]\n          : layer.getBounds().getCenter();\n        const siglas = p.nome.replace(\'DS \', \'\');\n        L.marker(ponto, {\n          interactive: false,\n          icon: L.divIcon({\n            className: \'\',\n            iconSize: null,\n            html: \'<div style="transform:translate(-50%,-50%);background:#1e3a8a;color:#fff;\' +\n                  \'padding:3px 8px;border-radius:6px;text-align:center;white-space:nowrap;\' +\n                  \'box-shadow:0 1px 3px rgba(0,0,0,.3);font-family:inherit">\' +\n                  \'<div style="font-size:13px;font-weight:700">\' + formatarMm(p.chuva_24h_mm) + \'</div>\' +\n                  \'<div style="font-size:10px;opacity:.85">DS \' + siglas + \'</div></div>\'\n          })\n        }).addTo(camadaChuva);\n      }\n    }).addTo(camadaChuva);\n  })\n  .catch(err => console.error(\'Erro ao carregar a chuva por distrito:\', err));\n\n// pluviômetros: um ponto por estação, com a chuva medida em 24 h\nfetch(\'/api/estacoes-chuva/\')\n  .then(r => r.json())\n  .then(dados => {\n    L.geoJSON(dados, {\n      pointToLayer: (feature, latlng) => L.circleMarker(latlng, {\n        radius: 6, weight: 2, color: \'#fff\', fillOpacity: 1,\n        fillColor: feature.properties.chuva_24h_mm === null ? \'#94a3b8\' : corChuva(feature.properties.chuva_24h_mm)\n      }),\n      onEachFeature: (feature, layer) => {\n        const p = feature.properties;\n        layer.bindTooltip(\'<strong>\' + p.nome + \'</strong> (\' + p.distrito + \')<br>\' +\n          formatarMm(p.chuva_24h_mm) + \' em 24h<br><span style="color:#64748b">pluviômetro CEMADEN</span>\');\n      }\n    }).addTo(camadaChuva);\n  })\n  .catch(err => console.error(\'Erro ao carregar os pluviômetros:\', err));\n\ndocument.getElementById(\'camada-chuva\')\n  .addEventListener(\'change\', function (e) {\n    if (e.target.checked) {\n      camadaChuva.addTo(map);\n      // por baixo dos distritos, para o clique no distrito continuar funcionando\n      camadaChuva.eachLayer(l => l.bringToBack && l.bringToBack());\n      legendaChuva.addTo(map);\n    } else {\n      map.removeLayer(camadaChuva);\n      legendaChuva.remove();\n    }\n    // o painel de risco descreve a cor dos distritos, que some com a chuva ligada\n    atualizarPainelRisco();\n    redesenharDistritos();\n  });\n\n\n// ─── Camada: áreas de risco (Defesa Civil) ──────────────────────\n// Fonte: Plano de Contingência 2024 da SEDEC. O plano identifica\n// comunidades DENTRO dos bairros: o bairro aparece porque contém\n// áreas de risco alto/muito alto, não porque esteja todo em risco.\nconst CORES_RISCO_AREA = { alagamento: \'#0891b2\', deslizamento: \'#b45309\', ambos: \'#be123c\' };\n\nfunction corRisco(tipos) {\n  return tipos.length > 1 ? CORES_RISCO_AREA.ambos : CORES_RISCO_AREA[tipos[0]];\n}\n\nfunction listaHtml(titulo, itens) {\n  if (!itens.length) return \'\';\n  return \'<p style="margin:8px 0 2px;font-weight:600">\' + titulo + \' (\' + itens.length + \')</p>\' +\n    \'<ul style="margin:0;padding-left:16px;max-height:140px;overflow:auto">\' +\n    itens.map(i => \'<li>\' + i + \'</li>\').join(\'\') + \'</ul>\';\n}\n\nconst camadaRisco = L.layerGroup();\n\nfetch(\'/api/areas-risco/\')\n  .then(r => r.json())\n  .then(dados => {\n    L.geoJSON(dados, {\n      style: f => ({\n        fillColor: corRisco(f.properties.tipos),\n        color: corRisco(f.properties.tipos),\n        weight: 1.5,\n        fillOpacity: 0.35\n      }),\n      onEachFeature: function (feature, layer) {\n        const p = feature.properties;\n        layer.bindTooltip(\'<strong>\' + p.bairro + \'</strong><br>\' + p.total_areas +\n          (p.total_areas === 1 ? \' área\' : \' áreas\') + \' de risco alto ou muito alto\', { sticky: true });\n        layer.bindPopup(\n          \'<div style="max-width:280px;font-size:12px">\' +\n          \'<strong style="font-size:14px">\' + p.bairro + \'</strong>\' +\n          \'<p style="margin:4px 0;color:#64748b">Contém áreas de risco alto ou muito alto (R3/R4). \' +\n          \'O risco está nas áreas listadas, não no bairro inteiro.</p>\' +\n          listaHtml(\'Deslizamento\', p.deslizamento) +\n          listaHtml(\'Alagamento\', p.alagamento) +\n          \'<p style="margin:8px 0 0;color:#94a3b8;font-size:11px">\' + p.fonte + \'</p></div>\'\n        );\n      }\n    }).addTo(camadaRisco);\n  })\n  .catch(err => console.error(\'Erro ao carregar áreas de risco:\', err));\n\ndocument.getElementById(\'camada-risco\')\n  .addEventListener(\'change\', function (e) {\n    if (e.target.checked) {\n      desligar(\'camada-arbo\');\n      desligar(\'camada-com\');\n      desligar(\'camada-vul\'); desligar(\'camada-perfil\');\n      camadaRisco.addTo(map);\n      // por cima dos distritos, para o clique abrir o detalhe do bairro...\n      camadaRisco.eachLayer(l => l.bringToFront && l.bringToFront());\n      // ...mas por baixo das unidades de saúde, que continuam clicáveis\n      if (map.hasLayer(camadaUnidades)) {\n        camadaUnidades.eachLayer(l => l.bringToFront && l.bringToFront());\n      }\n    } else {\n      map.removeLayer(camadaRisco);\n    }\n    document.getElementById(\'legenda-risco\').classList.toggle(\'hidden\', !e.target.checked);\n    atualizarPainelRisco();\n    redesenharDistritos();\n  });\n\n\n// ─── Camada: arboviroses por bairro (SINAN, histórico anual) ────\n// Incidência = casos prováveis (notificados exceto descartados) por\n// 10 mil habitantes, com a população do Censo 2022. O arquivo mais\n// recente da prefeitura é anual; a semana atual vem do InfoDengue.\nconst CORES_ARBO = [\'#ffffb2\', \'#fecc5c\', \'#fd8d3c\', \'#f03b20\', \'#bd0026\'];\nconst camadaArbo = L.layerGroup();\nlet quebrasArbo = [];\n\nconst fmt1 = v => v.toLocaleString(\'pt-BR\', { minimumFractionDigits: 1, maximumFractionDigits: 1 });\n\n// quebras por quantis: cada cor reúne ~1/5 dos bairros. Valores de\n// incidência variam muito de um ano para outro (epidemias), então\n// quebras fixas deixariam anos inteiros de uma cor só.\nfunction calcularQuebras(valores) {\n  const v = valores.filter(x => x !== null).sort((a, b) => a - b);\n  if (!v.length || v[0] === v[v.length - 1]) return [];\n  const q = [0.2, 0.4, 0.6, 0.8].map(p => v[Math.floor(p * (v.length - 1))]);\n  return [...new Set(q)];\n}\n\nfunction corArbo(valor) {\n  if (valor === null) return \'#e2e8f0\';\n  let i = 0;\n  while (i < quebrasArbo.length && valor > quebrasArbo[i]) i++;\n  return CORES_ARBO[Math.min(i, CORES_ARBO.length - 1)];\n}\n\nfunction desenharLegendaArbo(maximo) {\n  const limites = [0, ...quebrasArbo, maximo];\n  const div = document.getElementById(\'legenda-arbo\');\n  if (limites.length < 2 || maximo === 0) {\n    div.innerHTML = \'<p>Nenhum caso provável no período selecionado.</p>\';\n    return;\n  }\n  div.innerHTML = limites.slice(0, -1).map((ini, i) =>\n    \'<div class="flex items-center gap-2"><i class="inline-block size-3 rounded-sm" style="background:\' +\n    CORES_ARBO[i] + \'"></i> \' + fmt1(ini) + \' a \' + fmt1(limites[i + 1]) + \'</div>\'\n  ).join(\'\');\n}\n\nfunction carregarArbo() {\n  const ano = document.getElementById(\'arbo-ano\').value;\n  const doenca = document.getElementById(\'arbo-doenca\').value;\n  const params = new URLSearchParams({ doenca });\n  if (ano) params.set(\'ano\', ano);\n\n  fetch(\'/api/arboviroses-bairros/?\' + params)\n    .then(r => r.json())\n    .then(dados => {\n      // preenche a lista de anos na primeira carga\n      const seletor = document.getElementById(\'arbo-ano\');\n      if (!seletor.options.length && dados.anos) {\n        dados.anos.slice().reverse().forEach(a => seletor.add(new Option(a, a)));\n        seletor.value = dados.ano;\n      }\n\n      const valores = dados.features.map(f => f.properties.incidencia_10k);\n      quebrasArbo = calcularQuebras(valores);\n      desenharLegendaArbo(Math.max(0, ...valores.filter(x => x !== null)));\n\n      camadaArbo.clearLayers();\n      L.geoJSON(dados, {\n        style: f => ({\n          fillColor: corArbo(f.properties.incidencia_10k),\n          color: \'#7c2d12\', weight: 0.8, fillOpacity: 0.7\n        }),\n        onEachFeature: function (feature, layer) {\n          const p = feature.properties;\n          const nomes = { dengue: \'Dengue\', chikungunya: \'Chikungunya\', zika: \'Zika\' };\n          const linhas = Object.entries(p.por_doenca)\n            .map(([d, n]) => \'<li>\' + nomes[d] + \': \' + n.toLocaleString(\'pt-BR\') + \'</li>\').join(\'\');\n          layer.bindTooltip(\'<strong>\' + p.bairro + \'</strong><br>\' +\n            (p.incidencia_10k === null ? \'sem dado\' : fmt1(p.incidencia_10k) + \' por 10 mil hab.\'), { sticky: true });\n          layer.bindPopup(\n            \'<div style="font-size:12px;max-width:260px">\' +\n            \'<strong style="font-size:14px">\' + p.bairro + \'</strong> · \' + dados.ano +\n            \'<p style="margin:6px 0 2px;font-size:20px;font-weight:700">\' +\n            (p.incidencia_10k === null ? \'--\' : fmt1(p.incidencia_10k)) +\n            \' <span style="font-size:12px;font-weight:400;color:#64748b">por 10 mil hab.</span></p>\' +\n            \'<p style="margin:0;color:#64748b">\' + p.provaveis.toLocaleString(\'pt-BR\') + \' casos prováveis · \' +\n            p.populacao.toLocaleString(\'pt-BR\') + \' habitantes</p>\' +\n            \'<ul style="margin:6px 0 0;padding-left:16px">\' + linhas + \'</ul>\' +\n            \'<p style="margin:8px 0 0;color:#94a3b8;font-size:11px">Casos prováveis = notificados exceto descartados, \' +\n            \'por bairro de residência. \' + dados.fonte + \'.</p></div>\'\n          );\n        }\n      }).addTo(camadaArbo);\n\n      if (map.hasLayer(camadaArbo)) {\n        camadaArbo.eachLayer(l => l.bringToFront && l.bringToFront());\n        if (map.hasLayer(camadaUnidades)) camadaUnidades.eachLayer(l => l.bringToFront && l.bringToFront());\n      }\n    })\n    .catch(err => console.error(\'Erro ao carregar arboviroses:\', err));\n}\n\ndocument.getElementById(\'camada-arbo\')\n  .addEventListener(\'change\', function (e) {\n    if (e.target.checked) {\n      desligar(\'camada-risco\');\n      desligar(\'camada-com\');\n      desligar(\'camada-vul\'); desligar(\'camada-perfil\');\n      camadaArbo.addTo(map);\n      carregarArbo();\n    } else {\n      map.removeLayer(camadaArbo);\n    }\n    document.getElementById(\'controles-arbo\').classList.toggle(\'hidden\', !e.target.checked);\n    atualizarPainelRisco();\n    redesenharDistritos();\n  });\ndocument.getElementById(\'arbo-ano\').addEventListener(\'change\', carregarArbo);\ndocument.getElementById(\'arbo-doenca\').addEventListener(\'change\', carregarArbo);\n\n// ─── Card: arboviroses agora (InfoDengue, município) ────────────\nconst CORES_NIVEL = { 1: [\'#dcfce7\', \'#166534\'], 2: [\'#fef9c3\', \'#854d0e\'], 3: [\'#ffedd5\', \'#9a3412\'], 4: [\'#fee2e2\', \'#991b1b\'] };\nfetch(\'/api/arboviroses-resumo/\')\n  .then(r => r.json())\n  .then(({ resumo }) => {\n    if (!resumo) return;\n    const dm = s => s.slice(8, 10) + \'/\' + s.slice(5, 7);\n    document.getElementById(\'info-estimados\').innerText = resumo.estimados.toLocaleString(\'pt-BR\');\n    document.getElementById(\'info-faixa\').innerText =\n      \'entre \' + resumo.estimados_min + \' e \' + resumo.estimados_max + \' · \' + resumo.notificados + \' já notificados\';\n    const nivel = document.getElementById(\'info-nivel\');\n    const [fundo, texto] = CORES_NIVEL[resumo.nivel] || [\'#f1f5f9\', \'#334155\'];\n    nivel.innerText = resumo.nivel_nome;\n    nivel.style.background = fundo; nivel.style.color = texto;\n    nivel.title = resumo.nivel_texto;\n    document.getElementById(\'info-semana\').innerText =\n      \'SE \' + resumo.semana + \' · \' + dm(resumo.inicio) + \' a \' + dm(resumo.fim);\n    document.getElementById(\'card-infodengue\').classList.remove(\'hidden\');\n  })\n  .catch(err => console.error(\'Erro ao carregar o resumo do InfoDengue:\', err));\n\n\n// ─── Rede de apoio: abrigos, escolas e CRAS ─────────────────────\n// L.marker com divIcon vive no markerPane, acima de todos os\n// polígonos: nenhuma combinação de camadas esconde um abrigo.\nconst REDE = {\n  abrigo: { rotulo: \'Abrigo\', html: \'<div style="width:18px;height:18px;border-radius:3px;background:#15803d;border:2px solid #fff;box-shadow:0 1px 3px rgba(0,0,0,.4);color:#fff;font:700 10px/14px sans-serif;text-align:center">A</div>\', tamanho: 18 },\n  escola: { rotulo: \'Escola municipal\', html: \'<div style="width:10px;height:10px;border-radius:50%;background:#1e40af;border:1.5px solid #fff;box-shadow:0 1px 2px rgba(0,0,0,.4)"></div>\', tamanho: 10 },\n  cras:   { rotulo: \'CRAS\', html: \'<div style="width:10px;height:10px;transform:rotate(45deg);background:#ea580c;border:1.5px solid #fff;box-shadow:0 1px 2px rgba(0,0,0,.4)"></div>\', tamanho: 10 }\n};\nconst camadasRede = { abrigo: L.layerGroup(), escola: L.layerGroup(), cras: L.layerGroup() };\n\nfunction popupRede(p) {\n  const linhas = Object.entries(p.detalhe || {})\n    .filter(([k]) => ![\'CODESCOLA\', \'CEP\'].includes(k))\n    .map(([k, v]) => \'<li>\' + k.replaceAll(\'_\', \' \').toLowerCase() + \': \' + v + \'</li>\').join(\'\');\n  return \'<div style="font-size:12px;max-width:260px">\' +\n    \'<p style="margin:0;color:#64748b;font-size:11px">\' + REDE[p.tipo].rotulo + \'</p>\' +\n    \'<strong style="font-size:14px">\' + p.nome + \'</strong>\' +\n    \'<p style="margin:4px 0">\' + [p.endereco, p.bairro].filter(Boolean).join(\' · \') + \'</p>\' +\n    (linhas ? \'<ul style="margin:4px 0;padding-left:16px">\' + linhas + \'</ul>\' : \'\') +\n    (p.tipo === \'abrigo\' ? \'<p style="margin:6px 0 0;color:#b45309;font-size:11px">Cadastro: não indica se está aberto nem a capacidade.</p>\' : \'\') +\n    \'<p style="margin:6px 0 0;color:#94a3b8;font-size:11px">\' + p.fonte + \'</p></div>\';\n}\n\nfetch(\'/api/rede-apoio/\')\n  .then(r => r.json())\n  .then(dados => {\n    const contagem = { abrigo: 0, escola: 0, cras: 0 };\n    dados.features.forEach(f => {\n      const p = f.properties, cfg = REDE[p.tipo];\n      if (!cfg) return;\n      const [lon, lat] = f.geometry.coordinates;\n      L.marker([lat, lon], {\n        icon: L.divIcon({ className: \'\', html: cfg.html, iconSize: [cfg.tamanho, cfg.tamanho], iconAnchor: [cfg.tamanho / 2, cfg.tamanho / 2] }),\n        title: p.nome,\n        zIndexOffset: p.tipo === \'abrigo\' ? 1000 : 0  // abrigo por cima das escolas\n      }).bindPopup(popupRede(p)).addTo(camadasRede[p.tipo]);\n      contagem[p.tipo]++;\n    });\n    Object.entries(contagem).forEach(([tipo, n]) => {\n      document.getElementById(\'contador-\' + tipo).innerText = n ? \'(\' + n + \')\' : \'(indisponível)\';\n      if (!n) { const c = document.getElementById(\'camada-\' + tipo); c.checked = false; c.disabled = true; }\n      if (document.getElementById(\'camada-\' + tipo).checked) camadasRede[tipo].addTo(map);\n    });\n  })\n  .catch(err => console.error(\'Erro ao carregar a rede de apoio:\', err));\n\nObject.keys(camadasRede).forEach(tipo => {\n  document.getElementById(\'camada-\' + tipo).addEventListener(\'change\', e => {\n    if (e.target.checked) camadasRede[tipo].addTo(map); else map.removeLayer(camadasRede[tipo]);\n  });\n});\n\n\n// ─── Camada: comunidades de interesse social (2014) ─────────────\nconst CORES_COM = [\'#fff7bc\', \'#fee391\', \'#fec44f\', \'#ec7014\', \'#993404\'];\nconst NOMES_IND = { IND_ALAGAM: \'alagamento\', DENS_ESCOR: \'deslizamento\', DRENAGEM: \'drenagem (deficiência)\',\n  PAVIMENTAC: \'pavimentação (deficiência)\', ESGOTAMENT: \'esgotamento\', COLETA_LIX: \'coleta de lixo\',\n  Indice_COM: \'índice composto\' };\nconst camadaCom = L.layerGroup();\nlet quebrasCom = [];\n\nfunction comLigado() { return document.getElementById(\'camada-com\').checked; }\n\n// zero = sem indicação; as cores dividem só as comunidades com nota\nfunction corCom(v) {\n  if (v === null || v === undefined) return \'#e2e8f0\';\n  if (v <= 0) return \'#f8fafc\';\n  let i = 0;\n  while (i < quebrasCom.length && v > quebrasCom[i]) i++;\n  return CORES_COM[Math.min(i, CORES_COM.length - 1)];\n}\n\nfunction carregarCom() {\n  const ind = document.getElementById(\'com-indicador\').value;\n  fetch(\'/api/comunidades/?indicador=\' + ind).then(r => r.json()).then(dados => {\n    const positivos = dados.features.map(f => f.properties.valor).filter(v => v > 0);\n    quebrasCom = calcularQuebras(positivos);\n    const limites = [0, ...quebrasCom, Math.max(0, ...positivos)];\n    document.getElementById(\'legenda-com\').innerHTML =\n      \'<div class="flex items-center gap-2"><i class="inline-block size-3 rounded-sm border border-slate-300" style="background:#f8fafc"></i> 0 (sem indicação)</div>\' +\n      limites.slice(0, -1).map((ini, i) => \'<div class="flex items-center gap-2"><i class="inline-block size-3 rounded-sm" style="background:\' +\n        CORES_COM[i] + \'"></i> \' + fmt1(ini) + \' a \' + fmt1(limites[i + 1]) + \'</div>\').join(\'\');\n    camadaCom.clearLayers();\n    L.geoJSON(dados, {\n      style: f => ({ fillColor: corCom(f.properties.valor), color: \'#78350f\', weight: 0.6, fillOpacity: 0.75 }),\n      onEachFeature: (f, layer) => {\n        const p = f.properties;\n        const linhas = Object.entries(NOMES_IND).filter(([k]) => p.indicadores[k] !== null && p.indicadores[k] !== undefined)\n          .map(([k, n]) => \'<li>\' + n + \': \' + fmt1(p.indicadores[k]) + \'</li>\').join(\'\');\n        layer.bindTooltip(\'<strong>\' + p.nome + \'</strong><br>\' + (p.valor === null ? \'sem dado\' : fmt1(p.valor) + \' de 10\'), { sticky: true });\n        layer.bindPopup(\'<div style="font-size:12px;max-width:260px"><strong style="font-size:14px">\' + p.nome + \'</strong>\' +\n          \'<p style="margin:2px 0;color:#64748b">\' + p.bairro + (p.populacao_2014 ? \' · \' + p.populacao_2014.toLocaleString(\'pt-BR\') + \' hab. (2014)\' : \'\') + \'</p>\' +\n          (p.precariedade ? \'<p style="margin:4px 0">\' + p.precariedade + \'</p>\' : \'\') +\n          \'<ul style="margin:4px 0;padding-left:16px">\' + linhas + \'</ul>\' +\n          \'<p style="margin:6px 0 0;color:#94a3b8;font-size:11px">Notas de 0 a 10, maior = pior. Levantamento de 2014: retrato da estrutura, não da população atual.</p></div>\');\n      }\n    }).addTo(camadaCom);\n    if (map.hasLayer(camadaCom) && map.hasLayer(camadaUnidades)) {\n      camadaUnidades.eachLayer(l => l.bringToFront && l.bringToFront());\n    }\n  }).catch(err => console.error(\'Erro ao carregar comunidades:\', err));\n}\n\ndocument.getElementById(\'camada-com\').addEventListener(\'change\', e => {\n  if (e.target.checked) { desligar(\'camada-risco\'); desligar(\'camada-arbo\'); desligar(\'camada-vul\'); desligar(\'camada-perfil\'); camadaCom.addTo(map); carregarCom(); }\n  else map.removeLayer(camadaCom);\n  document.getElementById(\'controles-com\').classList.toggle(\'hidden\', !e.target.checked);\n  atualizarPainelRisco();\n  redesenharDistritos();\n});\ndocument.getElementById(\'com-indicador\').addEventListener(\'change\', carregarCom);\n\nfunction selectDistrict(id) {\n  const card = document.getElementById(\'district-detail-card\');\n  const d = situacao[id] || {};\n  const titulo = document.getElementById(\'selected-district-name\');\n  titulo.innerText = id || \'Distrito\';\n  titulo.style.color = COR_SELECAO;\n  document.getElementById(\'district-rain\').innerText = formatarMm(d.chuva_24h_mm);\n  document.getElementById(\'district-rain-label\').innerText =\n    d.estacao_24h ? \'Chuva 24h · \' + d.estacao_24h : \'Chuva 24h medida\';\n  document.getElementById(\'district-cases\').innerText = formatarMm(d.previsao_24h_mm);\n  document.getElementById(\'district-alerts\').innerText = d.alertas_abertos ?? \'--\';\n  card.title = (d.motivos || []).join(\'\\n\') || (\'Nível: \' + (d.nivel || \'sem dado\'));\n  card.classList.remove(\'hidden\');\n}\n\nfunction closeDistrictDetail() {\n  document.getElementById(\'district-detail-card\').classList.add(\'hidden\');\n  distritoSelecionado = null;\n  redesenharDistritos();\n}\n\n// ─── Camada: índice de vulnerabilidade por bairro (etapa 4b) ─────────\nconst camadaVul = L.layerGroup();\nconst CORES_VUL = [\'#f1eef6\', \'#d7b5d8\', \'#df65b0\', \'#dd1c77\', \'#980043\'];\nconst NOMES_VUL = { indice: \'Geral\', indice_estrutural: \'Estrutural\', indice_historico: \'Histórico\' };\n\nfunction vulLigado() { return document.getElementById(\'camada-vul\').checked; }\n\nfunction corVul(v) {\n  if (v === null || v === undefined) return \'#e2e8f0\';\n  return CORES_VUL[Math.min(Math.floor(v * CORES_VUL.length), CORES_VUL.length - 1)];\n}\n\nfunction carregarVul() {\n  const campo = document.getElementById(\'vul-indice\').value;\n  fetch(\'/api/vulnerabilidade/\').then(r => r.json()).then(dados => {\n    document.getElementById(\'legenda-vul\').innerHTML = CORES_VUL.map((c, i) =>\n      \'<div class="flex items-center gap-2"><i class="inline-block size-3 rounded-sm" style="background:\' + c + \'"></i> \' +\n      fmt1(i / CORES_VUL.length) + \' a \' + fmt1((i + 1) / CORES_VUL.length) + \'</div>\').join(\'\');\n    camadaVul.clearLayers();\n    L.geoJSON(dados, {\n      style: f => ({ fillColor: corVul(f.properties[campo]), color: \'#701a75\', weight: 0.6, fillOpacity: 0.75 }),\n      onEachFeature: (f, layer) => {\n        const p = f.properties;\n        const v = p[campo];\n        layer.bindTooltip(\'<strong>\' + p.nome + \'</strong><br>\' + NOMES_VUL[campo] + \': \' +\n          (v === null || v === undefined ? \'sem dado\' : fmt1(v)) + (p.posicao ? \' · \' + p.posicao + \'º de 94\' : \'\'), { sticky: true });\n        layer.bindPopup(\'<div style="font-size:12px;max-width:270px"><strong style="font-size:14px">\' + p.nome + \'</strong>\' +\n          \'<p style="margin:2px 0;color:#64748b">\' + (p.posicao ? p.posicao + \'º mais vulnerável de 94 · classe \' + p.classe : \'sem índice\') + \'</p>\' +\n          \'<ul style="margin:4px 0;padding-left:16px">\' +\n          \'<li>População em comunidades: \' + (p.pct_pop_comunidades === null ? \'sem dado\' : Math.round(p.pct_pop_comunidades * 100) + \'%\') + \'</li>\' +\n          \'<li>Risco médio das comunidades: \' + fmt1(p.risco_comunidades) + \' de 10</li>\' +\n          \'<li>Áreas de risco (Plano 2024): \' + p.areas_risco + \'</li>\' +\n          \'<li>Atendimentos por 10 mil hab. em dia de chuva forte: \' +\n          (p.atendimentos_10k_por_dia_forte === null ? \'sem dado\' : fmt1(p.atendimentos_10k_por_dia_forte)) + \'</li></ul>\' +\n          \'<p style="margin:6px 0 0;color:#94a3b8;font-size:11px">Índice relativo entre os bairros do Recife (0 a 1). \' +\n          \'Estrutural: cadastros. Histórico: Defesa Civil 2015-2024.</p></div>\');\n      }\n    }).addTo(camadaVul);\n    if (map.hasLayer(camadaUnidades)) camadaUnidades.eachLayer(l => l.bringToFront && l.bringToFront());\n  }).catch(err => console.error(\'Erro ao carregar a vulnerabilidade:\', err));\n}\n\ndocument.getElementById(\'camada-vul\').addEventListener(\'change\', e => {\n  if (e.target.checked) { desligar(\'camada-risco\'); desligar(\'camada-arbo\'); desligar(\'camada-com\'); desligar(\'camada-perfil\'); camadaVul.addTo(map); carregarVul(); }\n  else map.removeLayer(camadaVul);\n  document.getElementById(\'controles-vul\').classList.toggle(\'hidden\', !e.target.checked);\n  atualizarPainelRisco();\n  redesenharDistritos();\n});\ndocument.getElementById(\'vul-indice\').addEventListener(\'change\', carregarVul);\n\n// ─── Camada: perfis de risco dos bairros (agrupamento K-means) ───────\nconst camadaPerfil = L.layerGroup();\nconst CORES_PERFIL = [\'#b45309\', \'#0369a1\', \'#7c3aed\', \'#be123c\', \'#15803d\', \'#64748b\'];\n\nfunction perfilLigado() { return document.getElementById(\'camada-perfil\').checked; }\n\nfunction carregarPerfil() {\n  fetch(\'/api/perfis/\').then(r => r.json()).then(dados => {\n    const nomes = [...new Set(dados.features.map(f => f.properties.perfil))].sort();\n    const cor = nome => nome.startsWith(\'baixo risco\') ? \'#cbd5e1\' : CORES_PERFIL[nomes.indexOf(nome) % CORES_PERFIL.length];\n    document.getElementById(\'legenda-perfil\').innerHTML = nomes.map(n =>\n      \'<div class="flex items-center gap-2"><i class="inline-block size-3 rounded-sm" style="background:\' + cor(n) + \'"></i> \' + n +\n      \' (\' + dados.features.filter(f => f.properties.perfil === n).length + \')</div>\').join(\'\') +\n      \'<p class="text-slate-400">Bairros agrupados pelo tipo de risco: atendimentos, eventos e cadastros.</p>\';\n    camadaPerfil.clearLayers();\n    L.geoJSON(dados, {\n      style: f => ({ fillColor: cor(f.properties.perfil), color: \'#334155\', weight: 0.6, fillOpacity: 0.7 }),\n      onEachFeature: (f, layer) => layer.bindTooltip(\'<strong>\' + f.properties.nome + \'</strong><br>\' + f.properties.perfil, { sticky: true })\n    }).addTo(camadaPerfil);\n  }).catch(err => console.error(\'Erro ao carregar os perfis:\', err));\n}\n\ndocument.getElementById(\'camada-perfil\').addEventListener(\'change\', e => {\n  if (e.target.checked) { desligar(\'camada-risco\'); desligar(\'camada-arbo\'); desligar(\'camada-com\'); desligar(\'camada-vul\'); camadaPerfil.addTo(map); carregarPerfil(); }\n  else map.removeLayer(camadaPerfil);\n  document.getElementById(\'legenda-perfil\').classList.toggle(\'hidden\', !e.target.checked);\n  atualizarPainelRisco();\n  redesenharDistritos();\n});\n\n',
    'apps/mapa/templates/mapa/mapa.html': '{% extends \'components/app-shell.html\' %}\n{% load static %}\n\n{% block title %}Mapa de Monitoramento{% endblock %}\n{% block page_title %}Mapa{% endblock %}\n\n{% block head_extra %}\n  <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" />\n  <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>\n{% endblock %}\n\n{% block content %}\n          <header class="mb-6 grid grid-cols-[minmax(0,1fr)_auto] items-start gap-4 border-b border-slate-200 pb-5">\n            <div class="min-w-0">\n              <h1 class="truncate text-2xl font-bold text-slate-900 md:text-3xl">Mapa de Monitoramento</h1>\n              <p class="mt-1 text-sm text-slate-500">Distritos sanitários do Recife · atualização em tempo real</p>\n            </div>\n          </header>\n\n          <div class="grid min-h-[690px] gap-5 xl:grid-cols-[minmax(0,1fr)_320px]">\n\n            <!-- Mapa Leaflet -->\n            <section\n              class="relative min-h-[570px] overflow-hidden rounded-lg border border-slate-200 bg-slate-100 shadow-sm"\n              aria-label="Mapa dos distritos sanitários do Recife">\n\n              <div id="map" class="absolute inset-0 z-0"></div>\n\n              <div\n                class="pointer-events-none absolute left-5 top-5 z-10 rounded-md border border-slate-200 bg-white/95 px-3 py-2 text-xs font-semibold shadow-sm flex items-center gap-2">\n                <i data-lucide="map-pinned" class="text-blue-600 w-4 h-4"></i> Recife · PE\n              </div>\n\n              <!-- Card Flutuante de Detalhes -->\n              <div id="district-detail-card"\n                class="hidden absolute inset-x-3 bottom-3 z-20 rounded-lg border border-slate-200 bg-white p-4 shadow-md md:inset-x-auto md:bottom-5 md:left-5 md:w-80">\n                <div class="flex items-start justify-between">\n                  <div>\n                    <p class="text-xs text-slate-500">Distrito selecionado</p>\n                    <h2 id="selected-district-name" class="text-xl font-bold text-slate-900">DS VI</h2>\n                  </div>\n                  <button onclick="closeDistrictDetail()" class="p-1 text-slate-400 hover:text-slate-600">\n                    <i data-lucide="x" class="w-5 h-5"></i>\n                  </button>\n                </div>\n                <div class="mt-3 grid grid-cols-3 gap-2 text-center">\n                  <div class="rounded bg-slate-100 p-2">\n                    <i data-lucide="cloud-rain" class="mx-auto text-blue-600 w-4 h-4"></i>\n                    <strong id="district-rain" class="mt-1 block text-sm">--</strong>\n                    <small id="district-rain-label" class="text-[10px] text-slate-500">Chuva 24h</small>\n                  </div>\n                  <div class="rounded bg-slate-100 p-2">\n                    <i data-lucide="cloud-sun-rain" class="mx-auto text-blue-600 w-4 h-4"></i>\n                    <strong id="district-cases" class="mt-1 block text-sm">--</strong>\n                    <small class="text-[10px] text-slate-500">Previsão 24h</small>\n                  </div>\n                  <div class="rounded bg-slate-100 p-2">\n                    <i data-lucide="building-2" class="mx-auto text-blue-600 w-4 h-4"></i>\n                    <strong id="district-alerts" class="mt-1 block text-sm">--</strong>\n                    <small class="text-[10px] text-slate-500">Alertas abertos</small>\n                  </div>\n                </div>\n              </div>\n            </section>\n\n            <!-- Painel Lateral -->\n            <aside class="space-y-5">\n              <div class="rounded-lg border border-slate-200 bg-white p-5 shadow-sm">\n                <h2 class="flex items-center gap-2 font-bold text-slate-900">\n                  <i data-lucide="layers-3" class="text-blue-600 w-5 h-5"></i> Camadas do mapa\n                </h2>\n                <div class="mt-4 space-y-3">\n                  <p class="text-[11px] font-semibold uppercase tracking-wide text-slate-400">Clima</p>\n                  <label class="flex cursor-pointer items-center gap-3 text-sm">\n                    <input type="checkbox" id="camada-chuva" class="size-4 accent-blue-600"> Chuva medida\n                    <span class="text-xs text-slate-400">(CEMADEN)</span>\n                  </label>\n                  <p class="pt-2 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Risco</p>\n                  <label class="flex cursor-pointer items-center gap-3 text-sm">\n                    <input type="checkbox" id="camada-risco" class="size-4 accent-blue-600"> Áreas de risco\n                    <span class="text-xs text-slate-400">(Defesa Civil)</span>\n                  </label>\n                  <div id="legenda-risco" class="hidden -mt-1 ml-7 space-y-1 text-[11px] text-slate-600">\n                    <div class="flex items-center gap-2"><i class="inline-block size-3 rounded-sm" style="background:#0891b2"></i> alagamento</div>\n                    <div class="flex items-center gap-2"><i class="inline-block size-3 rounded-sm" style="background:#b45309"></i> deslizamento</div>\n                    <div class="flex items-center gap-2"><i class="inline-block size-3 rounded-sm" style="background:#be123c"></i> os dois</div>\n                    <p class="text-slate-400">Bairros que contêm áreas de risco alto ou muito alto</p>\n                  </div>\n                  <label class="flex cursor-pointer items-center gap-3 text-sm">\n                    <input type="checkbox" id="camada-com" class="size-4 accent-blue-600"> Comunidades\n                    <span class="text-xs text-slate-400">(2014)</span>\n                  </label>\n                  <div id="controles-com" class="hidden -mt-1 ml-7 space-y-2 text-[11px] text-slate-600">\n                    <select id="com-indicador" class="rounded border border-slate-300 px-1.5 py-1 text-xs" aria-label="Indicador">\n                      <option value="alagamento">Alagamento</option>\n                      <option value="deslizamento">Deslizamento</option>\n                      <option value="indice">Precariedade (índice)</option>\n                    </select>\n                    <div id="legenda-com" class="space-y-1"></div>\n                    <p class="text-slate-400">Comunidades de Interesse Social, levantamento de 2014. Nota 0 a 10, maior = pior.</p>\n                  </div>\n                  <label class="flex cursor-pointer items-center gap-3 text-sm">\n                    <input type="checkbox" id="camada-vul" class="size-4 accent-blue-600"> Vulnerabilidade\n                    <span class="text-xs text-slate-400">(índice por bairro)</span>\n                  </label>\n                  <div id="controles-vul" class="hidden -mt-1 ml-7 space-y-2 text-[11px] text-slate-600">\n                    <select id="vul-indice" class="rounded border border-slate-300 px-1.5 py-1 text-xs" aria-label="Índice">\n                      <option value="indice">Geral</option>\n                      <option value="indice_estrutural">Estrutural (cadastros)</option>\n                      <option value="indice_historico">Histórico (atendimentos em chuva forte)</option>\n                    </select>\n                    <div id="legenda-vul" class="space-y-1"></div>\n                    <p class="text-slate-400">0 = menos vulnerável, 1 = mais, comparando os 94 bairros entre si.</p>\n                  </div>\n                  <label class="flex cursor-pointer items-center gap-3 text-sm">\n                    <input type="checkbox" id="camada-perfil" class="size-4 accent-blue-600"> Perfis de risco\n                    <span class="text-xs text-slate-400">(tipo de risco por bairro)</span>\n                  </label>\n                  <div id="legenda-perfil" class="hidden -mt-1 ml-7 space-y-1 text-[11px] text-slate-600"></div>\n                  <p class="pt-2 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Saúde</p>\n                  <label class="flex cursor-pointer items-center gap-3 text-sm">\n                    <input type="checkbox" id="camada-arbo" class="size-4 accent-blue-600"> Arboviroses por bairro\n                    <span class="text-xs text-slate-400">(histórico)</span>\n                  </label>\n                  <div id="controles-arbo" class="hidden -mt-1 ml-7 space-y-2 text-[11px] text-slate-600">\n                    <div class="flex gap-2">\n                      <select id="arbo-ano" class="rounded border border-slate-300 px-1.5 py-1 text-xs" aria-label="Ano"></select>\n                      <select id="arbo-doenca" class="rounded border border-slate-300 px-1.5 py-1 text-xs" aria-label="Doença">\n                        <option value="todas">Todas</option>\n                        <option value="dengue">Dengue</option>\n                        <option value="chikungunya">Chikungunya</option>\n                        <option value="zika">Zika</option>\n                      </select>\n                    </div>\n                    <div id="legenda-arbo" class="space-y-1"></div>\n                    <p class="text-slate-400">Casos prováveis por 10 mil habitantes, por bairro de residência</p>\n                  </div>\n                  <label class="flex cursor-pointer items-center gap-3 text-sm">\n                    <input type="checkbox" checked id="camada-unidades" class="size-4 accent-blue-600"> Unidades de saúde\n                    <span id="contador-unidades" class="text-xs text-slate-400"></span>\n                  </label>\n                  <p class="pt-2 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Rede de apoio</p>\n                  <label class="flex cursor-pointer items-center gap-3 text-sm">\n                    <input type="checkbox" checked id="camada-abrigo" class="size-4 accent-blue-600"> <i class="grid size-4 place-items-center rounded-[3px] border border-white bg-green-700 text-[9px] font-bold not-italic text-white shadow">A</i> Abrigos\n                    <span id="contador-abrigo" class="text-xs text-slate-400"></span>\n                  </label>\n                  <label class="flex cursor-pointer items-center gap-3 text-sm">\n                    <input type="checkbox" id="camada-escola" class="size-4 accent-blue-600"> <i class="inline-block size-2.5 rounded-full border border-white bg-blue-800 shadow"></i> Escolas municipais\n                    <span id="contador-escola" class="text-xs text-slate-400"></span>\n                  </label>\n                  <label class="flex cursor-pointer items-center gap-3 text-sm">\n                    <input type="checkbox" id="camada-cras" class="size-4 accent-blue-600"> <i class="inline-block size-2.5 rotate-45 border border-white bg-orange-600 shadow"></i> CRAS\n                    <span id="contador-cras" class="text-xs text-slate-400"></span>\n                  </label>\n                  <p class="-mt-1 ml-7 text-[11px] text-slate-400">O cadastro de abrigos não indica se estão abertos nem a capacidade.</p>\n                </div>\n              </div>\n\n              <div id="painel-risco" class="rounded-lg border border-slate-200 bg-white p-5 shadow-sm transition-opacity">\n                <h2 class="font-bold text-slate-900">Nível de risco</h2>\n                <div class="mt-4 space-y-3">\n                  <div class="flex items-center justify-between text-sm">\n                    <span>Alto</span>\n                    <span\n                      class="inline-flex items-center rounded-full bg-red-100 px-2.5 py-0.5 text-xs font-semibold text-red-800">Alto</span>\n                  </div>\n                  <div class="flex items-center justify-between text-sm">\n                    <span>Médio</span>\n                    <span\n                      class="inline-flex items-center rounded-full bg-amber-100 px-2.5 py-0.5 text-xs font-semibold text-amber-800">Médio</span>\n                  </div>\n                  <div class="flex items-center justify-between text-sm">\n                    <span>Normal</span>\n                    <span\n                      class="inline-flex items-center rounded-full bg-green-100 px-2.5 py-0.5 text-xs font-semibold text-green-800">Normal</span>\n                  </div>\n                  <div class="flex items-center justify-between text-sm">\n                    <span>Sem dado</span>\n                    <span\n                      class="inline-flex items-center rounded-full bg-slate-100 px-2.5 py-0.5 text-xs font-semibold text-slate-600">Sem dado</span>\n                  </div>\n                  <p class="text-[11px] text-slate-400">Gatilhos de chuva medida (CEMADEN), previsão e maré. Passe o mouse no card do distrito para ver o motivo.</p>\n                </div>\n              </div>\n\n              <div id="card-infodengue" class="hidden rounded-lg border border-slate-200 bg-white p-5 shadow-sm">\n                <h2 class="flex items-center gap-2 font-bold text-slate-900">Arboviroses agora\n                  <span class="rounded-full bg-emerald-100 px-2 py-0.5 text-[10px] font-semibold uppercase text-emerald-800">InfoDengue</span>\n                </h2>\n                <p class="mt-1 text-[11px] text-slate-500">Recife inteiro · semana mais recente</p>\n                <p class="mt-3 text-2xl font-bold text-slate-900"><span id="info-estimados">--</span> <small class="text-sm font-medium text-slate-500">casos estimados</small></p>\n                <p id="info-faixa" class="text-xs text-slate-500"></p>\n                <p class="mt-2 flex items-center gap-2 text-xs text-slate-600">\n                  <span id="info-nivel" class="rounded-full px-2 py-0.5 text-[11px] font-semibold"></span>\n                  <span id="info-semana"></span>\n                </p>\n                <p class="mt-2 text-[11px] text-slate-400">Dado municipal: não varia por bairro. O mapa mostra o histórico por bairro.</p>\n              </div>\n\n              <div class="rounded-md bg-blue-50 p-4 text-xs leading-5 text-blue-700 border border-blue-100">\n                Selecione um distrito no mapa para visualizar chuva acumulada, casos e alertas vigentes.\n              </div>\n            </aside>\n\n          </div>\n      \n{% endblock %}\n\n{% block scripts %}\n  <script src="{% static \'mapa/mapa.js\' %}"></script>\n{% endblock %}',
    'apps/mapa/urls.py': 'from django.urls import path\n\nfrom . import views\n\nurlpatterns = [\n    path("mapa/", views.mapa_view, name="mapa"),\n    path("api/situacao-distritos/", views.get_situacao_distritos, name="api_situacao_distritos"),\n    path("api/perfis/", views.get_perfis_geojson, name="api_perfis"),\n    path("api/vulnerabilidade/", views.get_vulnerabilidade_geojson, name="api_vulnerabilidade"),\n    path("api/distritos/", views.get_distritos_geojson, name="api_distritos"),\n    path("api/unidades/", views.get_unidades_geojson, name="api_unidades"),\n    path("api/chuva-distritos/", views.get_chuva_distritos_geojson, name="api_chuva_distritos"),\n    path("api/estacoes-chuva/", views.get_estacoes_chuva_geojson, name="api_estacoes_chuva"),\n    path("api/areas-risco/", views.get_areas_risco_geojson, name="api_areas_risco"),\n    path("api/arboviroses-bairros/", views.get_arboviroses_bairros_geojson, name="api_arboviroses_bairros"),\n    path("api/arboviroses-resumo/", views.get_arboviroses_resumo, name="api_arboviroses_resumo"),\n    path("api/comunidades/", views.get_comunidades_geojson, name="api_comunidades"),\n    path("api/rede-apoio/", views.get_rede_apoio_geojson, name="api_rede_apoio"),\n]\n',
    'apps/mapa/views.py': '"""Mapa e APIs GeoJSON que ele consome."""\n\nfrom apps.painel.situacao import situacao_por_distrito\n\nfrom django.http import JsonResponse\nfrom django.shortcuts import redirect, render\nfrom apps.fontes import painel_chuva\nfrom apps.fontes.repositorios import arboviroses as repo_arboviroses\nfrom apps.fontes.repositorios import referencia as repo_referencia\n\n\ndef mapa_view(request):\n    return render(request, "mapa/mapa.html")\n\n\ndef get_distritos_geojson(request):\n    """Distritos sanitários do Recife (8, desde a reorganização de 2014).\n\n    O GeoJSON do portal da prefeitura traz apenas o campo numérico\n    `cdistscodi` (1 a 8); a conversão para "DS I"..."DS VIII" é feita\n    no front-end.\n    """\n    features = repo_referencia.distritos_features()\n    return JsonResponse({"type": "FeatureCollection", "features": features})\n\n\ndef get_unidades_geojson(request):\n    """Unidades de saúde como GeoJSON, prontas para o Leaflet.\n\n    Aceita ?tipo=2 (ou repetido) para filtrar por código de tipo CNES.\n    Unidades sem coordenada ficam de fora: quebrariam a camada do mapa.\n    """\n    try:\n        tipos = [int(t) for t in request.GET.getlist("tipo")]\n    except ValueError:\n        return JsonResponse({"erro": "parâmetro \'tipo\' deve ser numérico"}, status=400)\n\n    features = [\n        {\n            "type": "Feature",\n            "geometry": u["localizacao"],\n            "properties": {\n                "nome": u.get("nome"),\n                "tipo": u.get("tipo"),\n                "codigo_tipo": u.get("codigo_tipo"),\n                "bairro": u.get("bairro"),\n                "turno": u.get("turno"),\n            },\n        }\n        for u in repo_referencia.unidades_saude(tipos)\n    ]\n\n    return JsonResponse({"type": "FeatureCollection", "features": features})\n\n\ndef get_chuva_distritos_geojson(request):\n    """Distritos coloridos pela chuva medida em 24 h (pior pluviômetro do distrito)."""\n    return JsonResponse(painel_chuva.chuva_por_distrito_geojson(repo_referencia.distritos_features()))\n\n\ndef get_estacoes_chuva_geojson(request):\n    """Pluviômetros do CEMADEN como pontos, com a chuva das últimas 24 h."""\n    return JsonResponse(painel_chuva.estacoes_geojson())\n\n\ndef get_areas_risco_geojson(request):\n    """Bairros que contêm áreas de risco alto ou muito alto (R3/R4).\n\n    Fonte: Plano de Contingência 2024 da Defesa Civil do Recife. O plano\n    identifica comunidades DENTRO dos bairros; o bairro na camada indica que\n    ele contém essas áreas, não que esteja todo em risco.\n    """\n    features = [\n        {\n            "type": "Feature",\n            "geometry": a["geometria"],\n            "properties": {\n                "bairro": a["bairro"],\n                "tipos": a["tipos"],\n                "alagamento": a["alagamento"],\n                "deslizamento": a["deslizamento"],\n                "total_areas": a["total_areas"],\n                "nivel": a["nivel"],\n                "fonte": a["fonte"],\n            },\n        }\n        for a in repo_referencia.areas_risco()\n    ]\n    return JsonResponse({"type": "FeatureCollection", "features": features})\n\n\nDOENCAS_ARBO = ("dengue", "chikungunya", "zika")\n\n\ndef get_arboviroses_bairros_geojson(request):\n    """Casos prováveis e incidência por bairro, num ano. Histórico: o arquivo\n    mais recente da prefeitura é de 2025; a semana atual vem do InfoDengue.\n\n    ?ano=2025 (padrão: o mais recente)  ?doenca=dengue|chikungunya|zika|todas\n    """\n    anos = repo_arboviroses.anos_por_bairro()\n    if not anos:\n        return JsonResponse({"type": "FeatureCollection", "features": [], "anos": []})\n\n    try:\n        ano = int(request.GET.get("ano", anos[-1]))\n    except ValueError:\n        return JsonResponse({"erro": "ano inválido"}, status=400)\n    doenca = request.GET.get("doenca", "todas")\n    doencas = DOENCAS_ARBO if doenca == "todas" else (doenca,)\n    if not set(doencas) <= set(DOENCAS_ARBO):\n        return JsonResponse({"erro": "doença inválida"}, status=400)\n\n    por_bairro = {}\n    for r in repo_arboviroses.por_bairro(ano, doencas):\n        b = por_bairro.setdefault(r["chave"], {"populacao": r["populacao"], "por_doenca": {}})\n        b["por_doenca"][r["doenca"]] = r["provaveis"]\n\n    features = []\n    for bairro in repo_referencia.bairros():\n        dados = por_bairro.get(bairro["chave"])\n        if not dados:\n            continue\n        provaveis = sum(dados["por_doenca"].values())\n        populacao = dados["populacao"]\n        features.append({\n            "type": "Feature",\n            "geometry": bairro["geometria"],\n            "properties": {\n                "bairro": bairro["nome"],\n                "populacao": populacao,\n                "provaveis": provaveis,\n                "por_doenca": dados["por_doenca"],\n                "incidencia_10k": round(provaveis / populacao * 10_000, 1) if populacao else None,\n            },\n        })\n\n    return JsonResponse({\n        "type": "FeatureCollection",\n        "ano": ano, "anos": anos, "doenca": doenca,\n        "fonte": "SINAN, via Portal de Dados Abertos do Recife; população: IBGE, Censo 2022",\n        "features": features,\n    })\n\n\ndef get_arboviroses_resumo(request):\n    """Situação da semana na cidade (InfoDengue), para o painel do mapa."""\n    resumo = repo_arboviroses.resumo_semana_cidade()\n    return JsonResponse({"resumo": resumo})\n\n\nINDICADORES_COMUNIDADE = {"alagamento": "IND_ALAGAM", "deslizamento": "DENS_ESCOR", "indice": "Indice_COM"}\n\n\ndef get_comunidades_geojson(request):\n    """Comunidades de Interesse Social (levantamento de 2014).\n\n    ?indicador=alagamento|deslizamento|indice. Notas de 0 a 10; maior = pior,\n    conferido contra o Plano de Contingência 2024 (analises/comunidades/conferir_escalas.py).\n    """\n    campo = INDICADORES_COMUNIDADE.get(request.GET.get("indicador", "alagamento"))\n    if not campo:\n        return JsonResponse({"erro": "indicador inválido"}, status=400)\n    features = [\n        {\n            "type": "Feature",\n            "geometry": c["geometria"],\n            "properties": {\n                "nome": c["nome"], "bairro": c["bairro"],\n                "populacao_2014": c.get("populacao_2014"), "precariedade": c.get("precariedade"),\n                "valor": c["indicadores"].get(campo), "indicadores": c["indicadores"],\n            },\n        }\n        for c in repo_referencia.comunidades()\n    ]\n    return JsonResponse({"type": "FeatureCollection", "features": features})\n\n\nTIPOS_REDE = ("abrigo", "escola", "cras")\n\n\ndef get_rede_apoio_geojson(request):\n    """Abrigos, escolas e CRAS como pontos. ?tipo=abrigo|escola|cras (opcional)."""\n    tipo = request.GET.get("tipo")\n    if tipo and tipo not in TIPOS_REDE:\n        return JsonResponse({"erro": "tipo inválido"}, status=400)\n    features = [\n        {\n            "type": "Feature",\n            "geometry": p["localizacao"],\n            "properties": {\n                "tipo": p["tipo"],\n                "nome": p["nome"],\n                "bairro": p["bairro"],\n                "endereco": p["endereco"],\n                "detalhe": p.get("detalhe", {}),\n                "fonte": p["fonte"],\n            },\n        }\n        for p in repo_referencia.rede_apoio(tipo)\n    ]\n    return JsonResponse({"type": "FeatureCollection", "features": features})\n\n\ndef get_situacao_distritos(request):\n    """Nível de cada distrito (gatilhos reais), chuva, previsão e alertas abertos."""\n    return JsonResponse({"distritos": situacao_por_distrito()})\n\n\ndef get_vulnerabilidade_geojson(request):\n    """Bairros com o índice de vulnerabilidade (estrutural, histórico e geral)."""\n    indices = {v["chave"]: v for v in repo_referencia.vulnerabilidade()}\n    features = [{"type": "Feature", "geometry": b["geometria"], "properties": {**indices[b["chave"]], "nome": b["nome"]}}\n                for b in repo_referencia.bairros() if b["chave"] in indices]\n    return JsonResponse({"type": "FeatureCollection", "features": features,\n                         "fonte": "Comunidades (2014), Plano de Contingência 2024, Defesa Civil 2015-2024, IBGE 2022"})\n\n\ndef get_perfis_geojson(request):\n    """Bairros com o perfil de risco (agrupamento K-means)."""\n    perfis = {p["chave"]: p for p in repo_referencia.perfis()}\n    features = [{"type": "Feature", "geometry": b["geometria"], "properties": {**perfis[b["chave"]], "nome": b["nome"]}}\n                for b in repo_referencia.bairros() if b["chave"] in perfis]\n    return JsonResponse({"type": "FeatureCollection", "features": features})\n\n',
    'docs/decisoes/012-modelo-de-eventos.md': '# 012 — Modelo de eventos (REINDESC): a chuva prevê eventos; o modelo não foi aprovado; os gatilhos avisam 47% no Recife\n\n**Contexto.** O modelo de risco com a Defesa Civil falhou porque o alvo misturava evento e\nrotina (decisão 010). O REINDESC (CEMADEN) registra EVENTOS com data: 825 ocorrências de\n2016 a 2026 no Recife e em 6 municípios vizinhos (374 município-dias), 75% deslizamentos.\n\n**Método.** Unidade x dia (8 distritos do Recife + 6 municípios), 2016-2026. Entradas:\nchuva do pior pluviômetro (dia, véspera, 3 e 7 dias, 72 h antes, intensidade, chuva com\nmemória), maré na hora do pico de chuva (decisão 011), umidade do solo do ERA5-Land na\nvéspera, mês e unidade. Ajuste 2016-2022, limiar em 2023, teste 2024-2026 (anos nunca\nusados). Regressão logística e XGBoost; controle sem chuva e sem solo; régua: gatilhos\natuais. Avaliação da probabilidade (precisão média, Brier, calibração), margem de erro\npor bootstrap de dias e estabilidade ano a ano. Regra fixada antes, no Recife: precisão\nmédia >= controle + 0,02 com limite inferior da margem > 0, E F1 > melhor gatilho.\n\n**Resultados (teste 2024-2026).**\n| | Recife (36 eventos) | Região (145 eventos) |\n|---|---|---|\n| Precisão média com chuva e solo (XGBoost) | 0,113 | 0,347 |\n| Precisão média do controle | 0,015 | 0,055 |\n| F1 do modelo escolhido (XGBoost) | 0,08 | 0,20 |\n| F1 dos gatilhos (só ALTO) | 0,09 (recall 47%) | 0,20 (recall 76%) |\n| F1 da regressão logística (não escolhida) | 0,14 | 0,30 |\n\nMargem de erro da diferença para o controle, no Recife: +0,014 a +0,226 (99% dos sorteios).\nEstabilidade: com chuva e solo venceu o controle em todos os anos de 2020 a 2026.\nCalibração: na faixa de maior risco, previsto 4,6% e observado 4,5%.\nImportância: chuva de 3 dias 0,50; umidade do solo ~0,03 (célula de 9 km, grosseira).\n\n**Decisão.** NÃO APROVADO: passou no critério 1 (a chuva prevê eventos, com margem de erro\npositiva) e falhou no 2 por 0,01 de F1. O limiar, escolhido em 2023 (39 eventos), saiu em\n0,002 e gerou alertas demais. A regressão logística teria superado os gatilhos, mas não foi\na escolhida pela validação; isso fica como observação, não como resultado. Os gatilhos\natuais continuam no sistema.\n\n**Consequências.**\n- Primeira avaliação dos gatilhos contra eventos reais: avisariam 47% dos dias com evento\n  no Recife e 76% na região, com cerca de 10 alertas por evento.\n- O teste 2024-2026 está gasto. Próxima versão: limiar escolhido com vários anos de\n  validação; avaliação em 2027.\n- Nenhum evento de grande porte no período de teste: essa pergunta segue em aberto.\n',
    'ml/demanda.py': '"""Previsão de DEMANDA: quantos atendimentos reativos cada distrito deve ter por semana.\n\nPara planejar equipe (escalas, férias, estoque de lonas), não para alertar. Aqui o que\natrapalhava o modelo de alerta ajuda: o calendário da Defesa Civil (estação chuvosa,\ncampanhas, feriados) é exatamente a demanda que se quer prever.\n\nAlvo: soma semanal de atendimentos REATIVOS por distrito (gold.ml_distrito_dia, 2015-2024).\nEntradas (sabidas ao planejar): distrito, semana do ano, mês, feriados na semana, chuva\nda semana (no uso, a prevista ou a média histórica) e da semana anterior.\nModelo: XGBoost com objetivo de CONTAGEM (Poisson), não classificação.\nRégua: a média daquela semana do ano naquele distrito nos anos de treino (o "normal").\n\nRegra fixada ANTES de rodar: o modelo é aprovado se errar pelo menos 10% menos que a régua\n(erro absoluto médio, MAE) no teste 2022-2024.\n\nUso:\n    python -m ml.demanda\n"""\n\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.model_selection import GridSearchCV, TimeSeriesSplit\nfrom xgboost import XGBRegressor\n\nfrom dominio.feriados import feriados_recife\nfrom etl.destinos import obter_destino\n\nSAIDA = Path(__file__).resolve().parents[1] / "analises" / "ml" / "saida"\nTREINO, TESTE = range(2015, 2022), range(2022, 2025)\nENTRADAS = ["distrito_codigo", "semana", "mes", "feriados", "chuva_semana_mm", "chuva_semana_anterior_mm"]\nGRADE = {"n_estimators": [200, 400], "max_depth": [3, 5], "learning_rate": [0.05, 0.1]}\nGANHO_MINIMO = 0.10\n\n\ndef semanal(df):\n    """Tabela distrito x dia -> distrito x semana (semana começando na segunda)."""\n    df = df.copy()\n    df["data"] = pd.to_datetime(df["data"])\n    df["inicio"] = df["data"] - pd.to_timedelta(df["data"].dt.weekday, unit="D")\n    feriados = set()\n    for ano in range(df["data"].dt.year.min(), df["data"].dt.year.max() + 1):\n        feriados |= {pd.Timestamp(d) for d in feriados_recife(ano)}\n    df["feriado"] = df["data"].isin(feriados)\n    s = df.groupby(["distrito_codigo", "inicio"]).agg(\n        atendimentos=("atendimentos_reativos", "sum"), chuva_semana_mm=("chuva_dia_mm", "sum"),\n        feriados=("feriado", "sum"), dias=("data", "size")).reset_index()\n    s = s[s["dias"] == 7].sort_values(["distrito_codigo", "inicio"])\n    s["chuva_semana_anterior_mm"] = s.groupby("distrito_codigo")["chuva_semana_mm"].shift(1)\n    s["semana"] = s["inicio"].dt.isocalendar().week.astype(int).clip(upper=52)\n    s["mes"] = s["inicio"].dt.month\n    s["ano"] = s["inicio"].dt.year\n    return s\n\n\ndef regua(treino, teste):\n    """O \'normal\': média daquela semana do ano naquele distrito, nos anos de treino."""\n    normal = treino.groupby(["distrito_codigo", "semana"])["atendimentos"].mean()\n    return teste.set_index(["distrito_codigo", "semana"]).index.map(normal).to_numpy(dtype=float)\n\n\ndef executar(s, grade=None, avisar=print):\n    treino, teste = s[s["ano"].isin(TREINO)].sort_values("inicio"), s[s["ano"].isin(TESTE)]\n    busca = GridSearchCV(XGBRegressor(objective="count:poisson", tree_method="hist", random_state=42, n_jobs=-1),\n                         grade or GRADE, scoring="neg_mean_absolute_error", cv=TimeSeriesSplit(4), n_jobs=1)\n    busca.fit(treino[ENTRADAS].astype(float), treino["atendimentos"])\n    previsto = busca.best_estimator_.predict(teste[ENTRADAS].astype(float))\n    normal = regua(treino, teste)\n    real = teste["atendimentos"].to_numpy(dtype=float)\n    mae_m, mae_r = np.mean(np.abs(previsto - real)), np.nanmean(np.abs(normal - real))\n    aprovado = mae_m <= (1 - GANHO_MINIMO) * mae_r\n    avisar(f"treino {len(treino)} distrito-semanas | teste {len(teste)} | melhores {busca.best_params_}")\n    avisar(f"Erro médio por distrito e semana (teste 2022-2024): modelo {mae_m:.1f} | régua (o normal) {mae_r:.1f} "\n           f"atendimentos ({100 * (1 - mae_m / mae_r):+.0f}%)")\n    avisar("Por distrito:")\n    for d, g in teste.assign(prev=previsto, normal=normal).groupby("distrito_codigo"):\n        avisar(f"  DS {d}: real {g[\'atendimentos\'].mean():6.1f}/semana | erro modelo {np.mean(np.abs(g[\'prev\'] - g[\'atendimentos\'])):5.1f}"\n               f" | erro régua {np.nanmean(np.abs(g[\'normal\'] - g[\'atendimentos\'])):5.1f}")\n    imp = dict(sorted(zip(ENTRADAS, busca.best_estimator_.feature_importances_), key=lambda p: -p[1]))\n    avisar("Importância: " + ", ".join(f"{k} {v:.2f}" for k, v in imp.items()))\n    avisar(f"VEREDITO: {\'APROVADO\' if aprovado else \'NÃO APROVADO\'} (precisa errar pelo menos {GANHO_MINIMO:.0%} menos que a régua)")\n    return aprovado, mae_m, mae_r\n\n\ndef main():\n    SAIDA.mkdir(parents=True, exist_ok=True)\n    banco = obter_destino().banco\n    df = pd.DataFrame(list(banco["gold_ml_distrito_dia"].find({"ano": {"$gte": 2015, "$lte": 2024}},\n                                                              {"_id": 0, "distrito_codigo": 1, "data": 1,\n                                                               "atendimentos_reativos": 1, "chuva_dia_mm": 1})))\n    linhas = []\n    executar(semanal(df), avisar=lambda t: (print(t, flush=True), linhas.append(t)))\n    (SAIDA / "resultado_demanda.txt").write_text("\\n".join(linhas), encoding="utf-8")\n\n\nif __name__ == "__main__":\n    main()\n',
    'ml/dengue_clima.py': '"""Dengue com clima: temperatura e umidade ajudam a prever os casos de daqui a 4 semanas?\n\nA etapa 4c mostrou que a chuva sozinha não explica a dengue além do ciclo anual. O\nmosquito depende principalmente da TEMPERATURA (acelera o ciclo) e da UMIDADE. Aqui o\nmodelo prevê os casos estimados (InfoDengue) da semana t+4, sabendo o que se sabe na\nsemana t: os casos das últimas semanas e o clima das últimas 8 semanas.\n\n  com clima   casos recentes + temperatura, umidade e chuva (médias de 4 e 8 semanas)\n  sem clima   só os casos recentes (o "controle": a epidemia pela própria inércia)\n\nClima: ERA5-Land, média dos 8 distritos do Recife; chuva: tabela do modelo de risco.\nTreino 2014-2021 | teste 2022-2024 (2025 em diante: o ERA5-Land por unidade não cobre tudo).\n\nRegra fixada ANTES de rodar: o clima ajuda se o erro (MAE do log dos casos) com clima for\npelo menos 5% menor que sem clima, no teste.\n\nUso:\n    python -m ml.dengue_clima\n"""\n\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.model_selection import GridSearchCV, TimeSeriesSplit\nfrom xgboost import XGBRegressor\n\nfrom etl.destinos import obter_destino\n\nSAIDA = Path(__file__).resolve().parents[1] / "analises" / "ml" / "saida"\nHORIZONTE = 4\nTREINO, TESTE = range(2014, 2022), range(2022, 2025)\nCASOS = ["log_casos", "log_casos_1", "log_casos_2", "log_casos_4", "semana_sen", "semana_cos"]\nCLIMA = ["temp_4s", "temp_8s", "umidade_4s", "umidade_8s", "chuva_4s", "chuva_8s"]\nGRADE = {"n_estimators": [200, 400], "max_depth": [2, 3], "learning_rate": [0.05, 0.1]}\nGANHO_MINIMO = 0.05\n\n\ndef montar(dengue, clima, chuva):\n    """dengue [{inicio_semana, casos_est}], clima/chuva diários -> uma linha por semana com o alvo t+4."""\n    s = dengue.sort_values("inicio_semana").reset_index(drop=True)\n    s["inicio_semana"] = pd.to_datetime(s["inicio_semana"])\n    for nome, serie, col in (("temp", clima, "temp_media_c"), ("umidade", clima, "umidade_ar_pct"),\n                             ("chuva", chuva, "chuva_dia_mm")):\n        d = serie.copy()\n        d["data"] = pd.to_datetime(d["data"])\n        diario = d.groupby("data")[col].mean()\n        s[nome] = [diario.loc[i:i + pd.Timedelta(days=6)].mean() for i in s["inicio_semana"]]\n    s["log_casos"] = np.log1p(s["casos_est"])\n    for k in (1, 2, 4):\n        s[f"log_casos_{k}"] = s["log_casos"].shift(k)\n    for nome in ("temp", "umidade", "chuva"):\n        s[f"{nome}_4s"] = s[nome].rolling(4).mean()\n        s[f"{nome}_8s"] = s[nome].rolling(8).mean()\n    semana = s["inicio_semana"].dt.isocalendar().week.astype(float)\n    s["semana_sen"], s["semana_cos"] = np.sin(2 * np.pi * semana / 52), np.cos(2 * np.pi * semana / 52)\n    s["alvo"] = s["log_casos"].shift(-HORIZONTE)\n    s["ano"] = s["inicio_semana"].dt.year\n    return s.dropna(subset=CASOS + ["alvo"])\n\n\ndef executar(s, grade=None, avisar=print):\n    treino, teste = s[s["ano"].isin(TREINO)], s[s["ano"].isin(TESTE)].dropna(subset=CLIMA)\n    treino_clima = treino.dropna(subset=CLIMA)\n    erros = {}\n    for nome, entradas, base in (("com clima", CASOS + CLIMA, treino_clima), ("sem clima", CASOS, treino_clima)):\n        busca = GridSearchCV(XGBRegressor(tree_method="hist", random_state=42, n_jobs=-1), grade or GRADE,\n                             scoring="neg_mean_absolute_error", cv=TimeSeriesSplit(4), n_jobs=1)\n        busca.fit(base[entradas], base["alvo"])\n        previsto = busca.best_estimator_.predict(teste[entradas])\n        erros[nome] = float(np.mean(np.abs(previsto - teste["alvo"])))\n        if nome == "com clima":\n            imp = dict(sorted(zip(entradas, busca.best_estimator_.feature_importances_), key=lambda p: -p[1]))\n    aprovado = erros["com clima"] <= (1 - GANHO_MINIMO) * erros["sem clima"]\n    avisar(f"semanas: treino {len(treino_clima)} | teste {len(teste)} | previsão {HORIZONTE} semanas à frente")\n    avisar(f"Erro médio (log dos casos): com clima {erros[\'com clima\']:.3f} | sem clima {erros[\'sem clima\']:.3f} "\n           f"({100 * (1 - erros[\'com clima\'] / erros[\'sem clima\']):+.0f}%)")\n    avisar("  (0,10 no log ~ 10% de erro nos casos)")\n    avisar("Importância (com clima): " + ", ".join(f"{k} {v:.2f}" for k, v in list(imp.items())[:8]))\n    avisar(f"VEREDITO: {\'O CLIMA AJUDA\' if aprovado else \'O CLIMA NÃO AJUDA\'} (precisa de pelo menos {GANHO_MINIMO:.0%} menos erro)")\n    return aprovado, erros\n\n\ndef main():\n    SAIDA.mkdir(parents=True, exist_ok=True)\n    banco = obter_destino().banco\n    dengue = pd.DataFrame(list(banco["silver_arbovirose_semanal"].find(\n        {"doenca": "dengue", "ano": {"$gte": 2014, "$lte": 2024}}, {"_id": 0, "inicio_semana": 1, "casos_est": 1})))\n    clima = pd.DataFrame(list(banco["silver_clima_era5land_dia"].find(\n        {"unidade": {"$regex": "^DS "}, "ano": {"$gte": 2013}}, {"_id": 0, "data": 1, "temp_media_c": 1, "umidade_ar_pct": 1})))\n    chuva = pd.DataFrame(list(banco["gold_ml_distrito_dia"].find({}, {"_id": 0, "data": 1, "chuva_dia_mm": 1})))\n    linhas = []\n    executar(montar(dengue, clima, chuva), avisar=lambda t: (print(t, flush=True), linhas.append(t)))\n    (SAIDA / "resultado_dengue_clima.txt").write_text("\\n".join(linhas), encoding="utf-8")\n\n\nif __name__ == "__main__":\n    main()\n',
    'ml/perfis.py': '"""Perfis de risco dos bairros: agrupamento (K-means) dos 94 bairros pelo TIPO de risco.\n\nO índice de vulnerabilidade (4b) diz QUANTO um bairro é vulnerável; os perfis dizem DE QUE\nJEITO: encosta que desliza, planície que alaga, centro com imóveis antigos, baixo risco.\nCada perfil pede uma resposta diferente (vistoria de encosta, desobstrução de canal...).\n\nCaracterísticas de cada bairro (todas por 10 mil habitantes ou proporção, em escala log):\n  atendimentos da Defesa Civil 2015-2024 por tipo: deslizamento, alagamento, lona, vistoria\n  eventos do REINDESC (geológicos e hidrológicos) dentro do bairro\n  % da população em comunidades, risco médio das comunidades, áreas de risco, densidade\n\nO número de grupos (3 a 6) é escolhido pela silhueta (o quanto os grupos ficam separados).\nCada grupo recebe um nome pela característica que mais o distingue da média.\n\n  gold  gold.perfil_bairro\n\nUso:\n    python -m ml.perfis\n"""\n\nimport math\nfrom collections import defaultdict\nfrom datetime import datetime, timezone\n\nimport numpy as np\nimport pandas as pd\nfrom shapely.geometry import Point, shape\nfrom sklearn.cluster import KMeans\nfrom sklearn.metrics import silhouette_score\nfrom sklearn.preprocessing import StandardScaler\n\nfrom etl.comum.texto import normalizar\nfrom etl.derivados.ml_distrito_dia import APELIDOS_DC\nfrom etl.destinos import obter_destino\nfrom etl.destinos.base import Carga\n\nGRUPOS_TIPO = {"deslizamento": ("DESLIZ", "BARREIRA"), "alagamento": ("ALAGA", "INUNDA"), "lona": ("LONA",),\n               "vistoria": ("VISTORIA", "MONITORA")}\nCARACTERISTICAS = ["deslizamento_10k", "alagamento_10k", "lona_10k", "vistoria_10k", "eventos_geo_10k",\n                   "eventos_hidro_10k", "pct_pop_comunidades", "risco_comunidades", "areas_risco", "densidade"]\nNOMES = {"deslizamento_10k": "encosta com deslizamentos", "eventos_geo_10k": "encosta com deslizamentos",\n         "lona_10k": "encosta com deslizamentos", "alagamento_10k": "planície que alaga",\n         "eventos_hidro_10k": "planície que alaga", "vistoria_10k": "imóveis em risco (vistorias)",\n         "pct_pop_comunidades": "comunidades densas", "risco_comunidades": "comunidades densas",\n         "areas_risco": "áreas de risco mapeadas", "densidade": "comunidades densas"}\n\n\ndef caracteristicas(bairros, dc, eventos, vulnerabilidade):\n    """bairros {chave: {nome, populacao, area_km2, distrito_codigo, geometria}};\n    dc {chave: {grupo: total}}; eventos {chave: {"Geo": n, "Hidro": n}}; vulnerabilidade {chave: {...}}."""\n    linhas = []\n    for chave, b in bairros.items():\n        pop = b.get("populacao") or 0\n        if pop < 500:\n            continue\n        por10k = lambda n: math.log1p(10_000 * n / pop)  # noqa: E731\n        v = vulnerabilidade.get(chave, {})\n        linhas.append({"chave": chave, "bairro": b["nome"], "distrito_codigo": b.get("distrito_codigo"),\n                       **{f"{g}_10k": por10k(dc.get(chave, {}).get(g, 0)) for g in GRUPOS_TIPO},\n                       "eventos_geo_10k": por10k(eventos.get(chave, {}).get("Geo", 0)),\n                       "eventos_hidro_10k": por10k(eventos.get(chave, {}).get("Hidro", 0)),\n                       "pct_pop_comunidades": v.get("pct_pop_comunidades") or 0.0,\n                       "risco_comunidades": v.get("risco_comunidades") or 0.0,\n                       "areas_risco": math.log1p(v.get("areas_risco") or 0),\n                       "densidade": math.log1p(pop / max(b.get("area_km2") or 1, 0.1))})\n    return pd.DataFrame(linhas)\n\n\ndef agrupar(df, ks=range(3, 7), semente=42):\n    x = StandardScaler().fit_transform(df[CARACTERISTICAS])\n    melhor = max(ks, key=lambda k: silhouette_score(x, KMeans(k, n_init=20, random_state=semente).fit_predict(x)))\n    km = KMeans(melhor, n_init=20, random_state=semente).fit(x)\n    df = df.assign(grupo=km.labels_)\n    centros = pd.DataFrame(km.cluster_centers_, columns=CARACTERISTICAS)\n    nomes, usados = {}, defaultdict(int)\n    for g, c in centros.iterrows():\n        if c.max() < 0.3:\n            nome = "baixo risco"\n        else:\n            nome = NOMES[c.idxmax()]\n        usados[nome] += 1\n        nomes[g] = nome if usados[nome] == 1 else f"{nome} ({usados[nome]})"\n    df["perfil"] = df["grupo"].map(nomes)\n    return df, melhor, silhouette_score(x, km.labels_), centros.rename(index=nomes)\n\n\ndef ler(banco):\n    bairros = {b["chave"]: b for b in banco["silver_bairros"].find()}\n    dc = defaultdict(lambda: defaultdict(int))\n    for d in banco["silver_defesa_civil_bairro_dia"].find({"ano": {"$gte": 2015, "$lte": 2024}},\n                                                          {"bairro": 1, "por_tipo": 1, "por_ocorrencia": 1}):\n        chave = APELIDOS_DC.get(normalizar(d["bairro"]), normalizar(d["bairro"]))\n        for tipo, n in list((d.get("por_tipo") or {}).items()) + list((d.get("por_ocorrencia") or {}).items()):\n            for g, termos in GRUPOS_TIPO.items():\n                if any(t in tipo for t in termos):\n                    dc[chave][g] += n\n    formas = {k: shape(b["geometria"]) for k, b in bairros.items() if b.get("geometria")}\n    eventos = defaultdict(lambda: defaultdict(int))\n    for o in banco["silver_reindesc_ocorrencias"].find({"unidade": {"$regex": "^DS "}}):\n        if o.get("latitude") is None:\n            continue\n        p = Point(o["longitude"], o["latitude"])\n        chave = next((k for k, f in formas.items() if f.contains(p)), None)\n        if chave:\n            eventos[chave][o.get("tipologia")] += 1\n    vul = {v["chave"]: v for v in banco["gold_vulnerabilidade_bairro"].find()}\n    return bairros, dc, eventos, vul\n\n\ndef carregar(destino, avisar=print):\n    df = caracteristicas(*ler(destino.banco))\n    df, k, silhueta, centros = agrupar(df)\n    agora = datetime.now(timezone.utc)\n    linhas = [{**{c: (float(v) if isinstance(v, (float, np.floating)) else v) for c, v in r.items()},\n               "grupo": int(r["grupo"]), "coletado_em": agora} for r in df.to_dict("records")]\n    destino.carregar(Carga("gold.perfil_bairro", linhas, chaves=("chave",)))\n    avisar(f"{len(df)} bairros em {k} perfis (silhueta {silhueta:.2f}; acima de 0,25 os grupos são razoavelmente separados)")\n    for nome, g in df.groupby("perfil"):\n        avisar(f"  {nome:<34} {len(g):>2} bairros: {\', \'.join(g.sort_values(\'bairro\')[\'bairro\'].head(6))}"\n               + (" ..." if len(g) > 6 else ""))\n    avisar("\\nCentro de cada perfil (desvios em relação à média dos bairros):")\n    avisar(centros.round(1).to_string())\n\n\nif __name__ == "__main__":\n    carregar(obter_destino())\n',
    'rodar_lote2.sh': '#!/bin/bash\n# Lote 2: demanda (contagem), perfis de bairro (K-means) e dengue com clima.\nset -e\nsource .venv/Scripts/activate 2>/dev/null || source .venv/bin/activate\necho "== 1/4 testes";                      python -m pytest -q\necho "== 2/4 perfis de risco dos bairros"; python -m ml.perfis\necho "== 3/4 previsão de demanda";         python -m ml.demanda\necho "== 4/4 dengue com clima";            python -m ml.dengue_clima\necho "Lote 2 concluído. Resultados em analises/ml/saida/ e a camada \'Perfis de risco\' no mapa."\n',
    'tests/test_lote2.py': 'import math\nimport random\nfrom datetime import datetime, timedelta\n\nimport pandas as pd\nimport pytest\n\nfrom ml import demanda, dengue_clima, perfis\n\nGRADE = {"n_estimators": [80], "max_depth": [3], "learning_rate": [0.1]}\n\n\ndef _diario():\n    random.seed(2)\n    linhas = []\n    d = datetime(2015, 1, 1)\n    while d <= datetime(2024, 12, 31):\n        sazonal = 30 if d.month in (4, 5, 6, 7) else 8\n        for dist in (2, 7):\n            chuva = max(0.0, random.gauss(8 if d.month in (4, 5, 6) else 2, 10))\n            linhas.append({"distrito_codigo": dist, "data": d, "chuva_dia_mm": chuva,\n                           "atendimentos_reativos": max(0, int(random.gauss(sazonal * dist / 4 + chuva / 2, 3)))})\n        d += timedelta(1)\n    return pd.DataFrame(linhas)\n\n\ndef test_demanda_semanal_e_ganho_sobre_o_normal():\n    s = demanda.semanal(_diario())\n    assert set(s["dias"]) == {7} and s["chuva_semana_anterior_mm"].notna().sum() > 0\n    aprovado, mae_m, mae_r = demanda.executar(s, GRADE, avisar=lambda t: None)\n    assert mae_m < mae_r and aprovado                                     # a chuva da semana explica parte da demanda\n\n\ndef test_dengue_clima_detecta_quando_a_temperatura_antecede_os_casos():\n    random.seed(4)\n    semanas = pd.date_range("2013-06-02", "2024-12-29", freq="7D")\n    temp = [26 + 2 * math.sin(2 * math.pi * i / 52) + random.gauss(0, 1.2) for i in range(len(semanas))]\n    casos = [max(1.0, 30 + 25 * (sum(temp[max(0, i - 8):i - 3]) / 5 - 26) + random.gauss(0, 3)) if i > 8 else 30\n             for i in range(len(semanas))]\n    dengue = pd.DataFrame({"inicio_semana": semanas, "casos_est": casos})\n    dias = pd.date_range("2013-06-01", "2025-01-10")\n    t_dia = {d: temp[min(len(temp) - 1, (d - semanas[0]).days // 7)] for d in dias}\n    clima = pd.DataFrame({"data": dias, "temp_media_c": [t_dia[d] for d in dias], "umidade_ar_pct": 80.0})\n    chuva = pd.DataFrame({"data": dias, "chuva_dia_mm": 3.0})\n    aprovado, erros = dengue_clima.executar(dengue_clima.montar(dengue, clima, chuva), GRADE, avisar=lambda t: None)\n    assert aprovado and erros["com clima"] < erros["sem clima"]\n\n\ndef test_perfis_separam_encosta_de_planicie():\n    random.seed(1)\n    bairros, dc, eventos, vul = {}, {}, {}, {}\n    for i in range(30):\n        tipo = ["encosta", "planicie", "baixo"][i % 3]\n        chave = f"B{i}"\n        bairros[chave] = {"nome": chave, "populacao": 10_000, "area_km2": 2, "distrito_codigo": 1}\n        dc[chave] = {"deslizamento": 300 if tipo == "encosta" else 5, "alagamento": 200 if tipo == "planicie" else 3,\n                     "lona": 400 if tipo == "encosta" else 10, "vistoria": 20}\n        eventos[chave] = {"Geo": 6 if tipo == "encosta" else 0, "Hidro": 4 if tipo == "planicie" else 0}\n        vul[chave] = {"pct_pop_comunidades": 0.5 if tipo != "baixo" else 0.05, "risco_comunidades": 5, "areas_risco": 3}\n    df, k, silhueta, _ = perfis.agrupar(perfis.caracteristicas(bairros, dc, eventos, vul), ks=range(3, 5))\n    assert k == 3 and silhueta > 0.4\n    grupo = dict(zip(df["chave"], df["perfil"]))\n    assert grupo["B0"] == grupo["B3"] != grupo["B1"]                      # encostas juntas, planície à parte\n    assert "encosta" in grupo["B0"] and "alaga" in grupo["B1"]\n\n\n@pytest.mark.django_db\ndef test_api_dos_perfis(client, destino, monkeypatch):\n    from apps.fontes.repositorios import conexao\n    destino.banco["silver_bairros"].insert_one({"chave": "IBURA", "nome": "Ibura", "geometria": {"type": "Point", "coordinates": [0, 0]}})\n    destino.banco["gold_perfil_bairro"].insert_one({"chave": "IBURA", "perfil": "encosta com deslizamentos", "grupo": 0})\n    monkeypatch.setattr(conexao, "banco", lambda: destino.banco)\n    assert client.get("/api/perfis/").json()["features"][0]["properties"]["perfil"] == "encosta com deslizamentos"\n',
}
for caminho, conteudo in ARQUIVOS.items():
    Path(caminho).parent.mkdir(parents=True, exist_ok=True)
    Path(caminho).write_text(conteudo, encoding='utf-8')
print("Lote 2 aplicado. Agora: bash rodar_lote2.sh")
